import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test("Update a draft vendor", { tag: "@VEN-08" }, async ({ apiAs }) => {
    // Arrange: a vendor in status "draft" owned by the member's tenant
    const member = await apiAs("member");
    const created = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Acme Freight"),
        category: "logistics",
        contact_email: `ops-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
      },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = await created.json();
    expect(vendor.status).toBe("draft");

    // Act: change its contact email
    const newEmail = "billing@acmefreight.example";
    const res = await member.patch(`/api/vendors/${vendor.id}`, {
      data: { contact_email: newEmail },
    });

    // Assert: response status and updated field
    expect(res.status(), await res.text()).toBe(200);
    const updated = await res.json();
    expect(updated.contact_email).toBe(newEmail);
    expect(updated.status).toBe("draft");

    // Assert: audit event is recorded (may be written asynchronously)
    await expect
      .poll(
        async () => {
          const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
          if (audit.status() !== 200) return `status ${audit.status()}`;
          const body = (await audit.json()) as { items: { action: string }[] };
          return body.items.some((e) => e.action === "vendor.updated");
        },
        { message: "audit event vendor.updated recorded" },
      )
      .toBe(true);
  });
});
